// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.io.CleanupMode;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

class LmdbLegacyAllocationExtremumTest {

	@ParameterizedTest
	@CsvSource({ "dictionary,false", "dictionary,true", "free_ids,false", "free_ids,true" })
	void legacyAllocationRespectsTheEntireCommittedIdRange(String location, boolean crossesHeaderBoundary,
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig().setInlineLiterals(false);
		StoreProperties properties = new StoreProperties(directory.toFile());
		properties.setVersion(Integer.toString(LmdbStoreFormat.LEGACY_VERSION));
		properties.save();
		Path values = directory.resolve("values");
		ValueStore initial = new ValueStore(values.toFile(), properties, config);
		initial.close();

		long boundary = 1L << 49; // reference IDs at this ordinal first need a 0xff Varint header
		long upperOrdinal = crossesHeaderBoundary ? boundary : boundary - 1L;
		long lowerId = ValueIds.createId(ValueIds.T_BNODE, upperOrdinal - 1L);
		long upperId = ValueIds.createId(ValueIds.T_BNODE, upperOrdinal);
		byte[] lowerKey = ValueStoreRecordCodec.idKey(lowerId);
		byte[] upperKey = ValueStoreRecordCodec.idKey(upperId);
		assertEquals((byte) 0xfe, lowerKey[1]);
		assertEquals(crossesHeaderBoundary ? (byte) 0xff : (byte) 0xfe, upperKey[1]);
		BNode lower = SimpleValueFactory.getInstance().createBNode("low");
		BNode upper = SimpleValueFactory.getInstance().createBNode("high");
		if (location.equals("dictionary")) {
			putOwner(directory, lowerKey, lower);
			putOwner(directory, upperKey, upper);
		} else {
			LmdbCompatibilityFixtures.nativePut(directory, "free_ids", lowerKey, new byte[0]);
			LmdbCompatibilityFixtures.nativePut(directory, "free_ids", upperKey, new byte[0]);
		}

		ValueStore reopened = new ValueStore(values.toFile(), properties, config);
		try {
			assertFalse(reopened.hasTrustedReferenceCounts(), "the external writer leaves count authority unknown");
			assertFalse(reopened.isValueReclamationEnabled(), "untrusted counts must not authorize reclamation");
			if (location.equals("dictionary")) {
				assertEquals(lowerId, reopened.getId(lower));
				assertEquals(upperId, reopened.getId(upper));
				assertEquals(upper, reopened.getValue(upperId));
			}
			try {
				reopened.startTransaction(true);
				long replacementId = reopened.storeValue(SimpleValueFactory.getInstance().createBNode("new"));
				assertTrue(ValueIds.referenceOrdinal(replacementId) > upperOrdinal,
						"new allocations must exceed every committed dictionary and free ID");
				reopened.commit();
			} finally {
				reopened.rollback();
			}
			if (location.equals("dictionary")) {
				assertEquals(upperId, reopened.getId(upper));
				assertEquals(upper, reopened.getValue(upperId));
			}
		} finally {
			reopened.close();
		}
		if (location.equals("free_ids")) {
			assertNotNull(LmdbCompatibilityFixtures.nativeGet(directory, "free_ids", upperKey));
		}
	}

	private static void putOwner(Path directory, byte[] idKey, BNode value) throws Exception {
		byte[] data = ValueStoreRecordCodec.bnodeData(value);
		LmdbCompatibilityFixtures.nativePut(directory, null, idKey, data);
		LmdbCompatibilityFixtures.nativePut(directory, null, data, idKey);
	}
}
